      "step2d": "\u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u0986\u09ac\u09c7\u09a6\u09a8 \u09aa\u09c2\u09b0\u09a3 \u0995\u09b0\u09c1\u09a8, \u09af\u09be\u09a8\u09c7\u09b0 \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8 \u098f\u09ac\u0982 \u0985\u09a8\u09b2\u09be\u0987\u09a8\u09c7 \u09ab\u09bf \u09a6\u09bf\u09a8: \u09e7\u099f\u09bf \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf\u09b0 \u099c\u09a8\u09cd\u09af \u09eb\u09e7\u09ee \u099f\u09be\u0995\u09be, \u09e8\u099f\u09bf\u09b0 \u099c\u09a8\u09cd\u09af \u09ed\u09ea\u09ee \u099f\u09be\u0995\u09be\u0964",
      "step2docs": "\u098f\u09a8\u0986\u0987\u09a1\u09bf\u09b0 \u0995\u09aa\u09bf, \u09aa\u09be\u09b8\u09aa\u09cb\u09b0\u09cd\u099f \u09b8\u09be\u0987\u099c \u099b\u09ac\u09bf, \u09b6\u09bf\u0995\u09cd\u09b7\u09be\u0997\u09a4 \u09b8\u09a8\u09a6, \u09ae\u09c7\u09a1\u09bf\u0995\u09c7\u09b2 \u09b8\u09a8\u09a6",
      "step2m": "\u09ad\u09c1\u09b2 \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf \u09ac\u09c7\u099b\u09c7 \u09a8\u09c7\u0993\u09af\u09bc\u09be \u2014 \u09aa\u09b0\u09c7 \u09b6\u09cd\u09b0\u09c7\u09a3\u09bf \u09af\u09cb\u0997 \u0995\u09b0\u09a4\u09c7 \u09a8\u09a4\u09c1\u09a8 \u0986\u09ac\u09c7\u09a6\u09a8 \u0995\u09b0\u09a4\u09c7 \u09b9\u09af\u09bc\u0964",
      "step2t": "\u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u09b2\u09be\u0987\u09b8\u09c7\u09a8\u09cd\u09b8\u09c7\u09b0 \u0986\u09ac\u09c7\u09a6\u09a8 \u0995\u09b0\u09c1\u09a8 \u0993 \u09ab\u09bf \u09a6\u09bf\u09a8",
      "step3d": "\u0986\u09aa\u09a8\u09be\u09b0 \u09ac\u09bf\u0986\u09b0\u099f\u09bf\u098f \u09b8\u09be\u09b0\u09cd\u0995\u09c7\u09b2 \u0985\u09ab\u09bf\u09b8\u09c7 \u099f\u09cd\u09b0\u09be\u09ab\u09bf\u0995 \u09a8\u09bf\u09af\u09bc\u09ae \u0993 \u09b0\u09cb\u09a1 \u09b8\u09be\u0987\u09a8 \u09ac\u09bf\u09b7\u09af\u09bc\u09c7 \u09b2\u09bf\u0996\u09bf\u09a4 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u09a6\u09bf\u09a8\u0964",
      "step3docs": "\u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u09b2\u09be\u0987\u09b8\u09c7\u09a8\u09cd\u09b8, \u098f\u09a8\u0986\u0987\u09a1\u09bf \u0995\u09be\u09b0\u09cd\u09a1",
      "step3m": "\u09b0\u09cb\u09a1 \u09b8\u09be\u0987\u09a8\u09c7\u09b0 \u0985\u09a7\u09cd\u09af\u09be\u09af\u09bc \u09ac\u09be\u09a6 \u09a6\u09c7\u0993\u09af\u09bc\u09be \u2014 \u09b2\u09bf\u0996\u09bf\u09a4 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09b0 \u09ac\u09c7\u09b6\u09bf\u09b0\u09ad\u09be\u0997 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8 \u09b8\u09be\u0987\u09a8 \u0993 \u09a8\u09bf\u09af\u09bc\u09ae \u09a8\u09bf\u09af\u09bc\u09c7\u0964",
      "step3t": "\u09b2\u09bf\u0996\u09bf\u09a4 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09af\u09bc \u09aa\u09be\u09b8 \u0995\u09b0\u09c1\u09a8",
      "step4d": "\u09ae\u09cc\u0996\u09bf\u0995 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09c7\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0 \u09a6\u09bf\u09a8 \u098f\u09ac\u0982 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0\u09bf\u0995 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09af\u09bc \u0997\u09be\u09a1\u09bc\u09bf \u099a\u09be\u09b2\u09be\u09a8 (\u09aa\u09be\u09b0\u09cd\u0995\u09bf\u0982, \u09ae\u09cb\u09a1\u09bc, \u09aa\u09c7\u099b\u09a8\u09c7 \u099a\u09be\u09b2\u09be\u09a8\u09cb)\u0964",
      "step4docs": "\u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u09b2\u09be\u0987\u09b8\u09c7\u09a8\u09cd\u09b8, \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u09af\u09be\u09a8\u09ac\u09be\u09b9\u09a8",
      "step4m": "\u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09b0 \u09ae\u09be\u09a0\u09c7 \u0985\u09a8\u09c1\u09b6\u09c0\u09b2\u09a8 \u099b\u09be\u09a1\u09bc\u09be \u09af\u09be\u0993\u09af\u09bc\u09be \u2014 \u0986\u0997\u09c7 \u09aa\u09be\u09b0\u09cd\u0995\u09bf\u0982 \u0993 \u09aa\u09c7\u099b\u09a8\u09c7 \u099a\u09be\u09b2\u09be\u09a8\u09cb \u0985\u09a8\u09c1\u09b6\u09c0\u09b2\u09a8 \u0995\u09b0\u09c1\u09a8\u0964",
      "step4t": "\u09ae\u09cc\u0996\u09bf\u0995 \u0993 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0\u09bf\u0995 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09af\u09bc \u09aa\u09be\u09b8 \u0995\u09b0\u09c1\u09a8",
      "step5d": "\u09aa\u09be\u09b8 \u0995\u09b0\u09be\u09b0 \u09aa\u09b0 \u0985\u09a8\u09b2\u09be\u0987\u09a8\u09c7 \u09b8\u09cd\u09ae\u09be\u09b0\u09cd\u099f \u0995\u09be\u09b0\u09cd\u09a1\u09c7\u09b0 \u09ab\u09bf \u09a6\u09bf\u09a8: \u0985\u09aa\u09c7\u09b6\u09be\u09a6\u09be\u09b0 \u09ea,\u09e8\u09e7\u09e8 \u099f\u09be\u0995\u09be \u0985\u09a5\u09ac\u09be \u09aa\u09c7\u09b6\u09be\u09a6\u09be\u09b0 \u09e8,\u09ea\u09ee\u09ed \u099f\u09be\u0995\u09be\u0964",
      "step5docs": "\u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f \u09b0\u09b8\u09bf\u09a6, \u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u09b2\u09be\u0987\u09b8\u09c7\u09a8\u09cd\u09b8",
      "step5m": "\u09ab\u09b2 \u09aa\u09cd\u09b0\u0995\u09be\u09b6\u09c7\u09b0 \u0986\u0997\u09c7 \u099f\u09be\u0995\u09be \u09a6\u09c7\u0993\u09af\u09bc\u09be \u2014 \u0986\u0997\u09c7 \u09aa\u09be\u09b8\u09c7\u09b0 \u09ab\u09b2\u09be\u09ab\u09b2\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0985\u09aa\u09c7\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c1\u09a8\u0964",
      "step5t": "\u09aa\u09be\u09b8\u09c7\u09b0 \u09aa\u09b0 \u09b8\u09cd\u09ae\u09be\u09b0\u09cd\u099f \u0995\u09be\u09b0\u09cd\u09a1\u09c7\u09b0 \u09ab\u09bf \u09a6\u09bf\u09a8",
      "step6d": "\u09b8\u09cd\u09ae\u09be\u09b0\u09cd\u099f \u0995\u09be\u09b0\u09cd\u09a1 \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09e8 \u09a5\u09c7\u0995\u09c7 \u09e9 \u09ae\u09be\u09b8\u09c7\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09a4\u09c8\u09b0\u09bf \u09b9\u09af\u09bc\u0964 \u09b0\u09b8\u09bf\u09a6 \u09a8\u09bf\u09af\u09bc\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09ac\u09bf\u0986\u09b0\u099f\u09bf\u098f \u09b8\u09be\u09b0\u09cd\u0995\u09c7\u09b2 \u0985\u09ab\u09bf\u09b8 \u09a5\u09c7\u0995\u09c7 \u09b8\u0982\u0997\u09cd\u09b0\u09b9 \u0995\u09b0\u09c1\u09a8\u0964",
      "step6docs": "\u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f \u09b0\u09b8\u09bf\u09a6, \u09b6\u09bf\u0995\u09cd\u09b7\u09be\u09a8\u09ac\u09bf\u09b6 \u09b2\u09be\u0987\u09b8\u09c7\u09a8\u09cd\u09b8, \u098f\u09a8\u0986\u0987\u09a1\u09bf \u0995\u09be\u09b0\u09cd\u09a1",
      "step6m": "\u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f \u09b0\u09b8\u09bf\u09a6 \u09b9\u09be\u09b0\u09bf\u09af\u09bc\u09c7 \u09ab\u09c7\u09b2\u09be \u2014 \u09b0\u09b8\u09bf\u09a6\u099f\u09bf \u09af\u09a4\u09cd\u09a8\u09c7 \u09b0\u09be\u0996\u09c1\u09a8, \u0995\u09be\u09b0\u09cd\u09a1 \u09a8\u09bf\u09a4\u09c7 \u098f\u099f\u09bf \u09b2\u09be\u0997\u09ac\u09c7\u0964",
      "step6t": "\u09b8\u09cd\u09ae\u09be\u09b0\u09cd\u099f \u0995\u09be\u09b0\u09cd\u09a1 \u09b8\u0982\u0997\u09cd\u09b0\u09b9 \u0995\u09b0\u09c1\u09a8",
